// Local recording choreography. The normal exhibition never imports this file.
// Every frame uses the production scene, text, translation and audio controls.
import { exhibitionAdjacentVisitStep } from '../utils/exhibitionVisit';
import { exhibitionNarrationCue } from '../utils/exhibitionGuideAudio';

const wait = ms => new Promise(resolve => setTimeout(resolve, ms));
function workPassage(exhibition, sourceId) {
  const stop = exhibition.stops.find(item => item.block.source_id === sourceId);
  const index = exhibition.steps.findIndex(step => step.kind === 'passage' && step.stopIndex === stop?.index);
  if (index < 0) throw new Error(`Capture work missing: ${sourceId}`);
  return index;
}
async function until(check, timeout = 45000) {
  const start = performance.now();
  while (!check()) { if (performance.now()-start > timeout) throw new Error('Capture did not become ready'); await wait(100); }
}
function focusElements(selectors) {
  let mask=document.querySelector('.capture-focus');
  if(!mask){
    mask=document.createElement('div');mask.className='capture-focus';
    Object.assign(mask.style,{position:'fixed',inset:'0',pointerEvents:'none',zIndex:50});
    document.querySelector('.view-exhibition').append(mask);
  }
  mask.captureSelectors=selectors;
  if(mask.captureRunning)return;
  mask.captureRunning=true;
  function paintMask(){
    if(!mask.isConnected)return;
    const bounds=mask.getBoundingClientRect();
    const holes=mask.captureSelectors.map(group=>{
      const rectangles=(Array.isArray(group)?group:[group]).map(selector=>document.querySelector(selector)?.getBoundingClientRect()).filter(r=>r?.width&&r?.height);
      if(!rectangles.length)return '';
      const left=Math.min(...rectangles.map(r=>r.left)),top=Math.min(...rectangles.map(r=>r.top));
      const right=Math.max(...rectangles.map(r=>r.right)),bottom=Math.max(...rectangles.map(r=>r.bottom));
      return `<rect x="${left-bounds.left-7}" y="${top-bounds.top-7}" width="${right-left+14}" height="${bottom-top+14}" rx="2" fill="black"/>`;
    }).join('');
    const content=`<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%" viewBox="0 0 ${bounds.width} ${bounds.height}"><defs><mask id="capture-focus-holes"><rect width="100%" height="100%" fill="white"/>${holes}</mask></defs><rect width="100%" height="100%" fill="#171610" fill-opacity=".48" mask="url(#capture-focus-holes)"/></svg>`;
    if(mask.captureContent!==content){mask.innerHTML=content;mask.captureContent=content;}
    requestAnimationFrame(paintMask);
  }
  paintMask();
}
async function captureClick(element) {
  if (!element) throw new Error('Capture control missing');
  const bounds = element.getBoundingClientRect();
  const pulse = document.createElement('span');
  Object.assign(pulse.style, { position:'fixed', left:`${bounds.left + bounds.width / 2}px`, top:`${bounds.top + bounds.height / 2}px`, width:'42px', height:'42px', borderRadius:'50%', border:'2px solid #fffdf5', background:'#332e2440', boxShadow:'0 0 0 1px #332e2466', pointerEvents:'none', zIndex:10000 });
  const surface = element.closest('dialog') || document.querySelector('.view-exhibition');
  surface.append(pulse);
  pulse.animate([{ transform:'translate(-50%,-50%) scale(.65)', opacity:0 }, { transform:'translate(-50%,-50%) scale(.85)', opacity:1, offset:.16 }, { transform:'translate(-50%,-50%) scale(1.25)', opacity:0 }], { duration:850, easing:'ease-out' }).finished.then(() => pulse.remove());
  await wait(140);
  element.click();
}
function mark(name, detail = '') {
  document.documentElement.dataset.studyStatus = name;
  document.documentElement.dataset.studyTime = String(Date.now());
  document.documentElement.dataset.studyDetail = detail;
}
async function beginAudioCapture() {
  // A slate outside the finished clip gives the encoder an exact visual start.
  const slate=document.createElement('div');
  Object.assign(slate.style,{position:'fixed',inset:'0',background:'#d92be4',zIndex:20000,pointerEvents:'none'});
  document.querySelector('.view-exhibition').append(slate);
  await wait(200);
  slate.remove();
  const start=performance.now();
  mark('recording');
  return start;
}
function trackRecordedAudio(audio,start,text,wordIndex) {
  const segments=[];
  let current=null;
  const end=()=>{
    if(!current)return;
    current.duration=Math.max(0,audio.currentTime-current.mediaStart);
    current.wordEnd=wordIndex();
    if(current.duration>.02)segments.push(current);
    current=null;
  };
  const begin=()=>{
    if(current)return;
    current={src:audio.currentSrc,offset:(performance.now()-start)/1000,mediaStart:audio.currentTime,text:text()};
  };
  const nativePause=audio.pause;
  // The pause event is queued. Finish before Listen here replaces the source.
  audio.pause=function(){end();return nativePause.call(this);};
  audio.addEventListener('playing',begin);
  for(const event of ['pause','ended','waiting'])audio.addEventListener(event,end);
  return ()=>{
    end();audio.pause=nativePause;audio.removeEventListener('playing',begin);
    for(const event of ['pause','ended','waiting'])audio.removeEventListener(event,end);
    return segments;
  };
}
export async function recordGalleryStudy(exhibition, mode) {
  try {
    clearTimeout(exhibition._orientationTimer);
    exhibition.orientationActive = false;
    await wait(1500);
    if (['arrival', 'wall-writing', 'globe', 'rooms', 'afterword'].includes(mode)) {
      if (mode === 'arrival') {
        exhibition.goStep(-1, true);
        exhibition.startOrientation();
        exhibition.orientationIndex = 2;
        await exhibition.$nextTick();
        exhibition.positionOrientation();
      } else if (mode === 'afterword') {
        exhibition.goStep(exhibition.exhibition.closing.stepIndex, true);
      } else if (mode === 'wall-writing') {
        exhibition.goStep(exhibition.exhibition.rooms[0].introStep, true);
      } else {
        const sourceId = mode === 'globe' ? 'interactive.travels.globe' : 'fragments:memory-time-self';
        exhibition.goStep(workPassage(exhibition.exhibition, sourceId), true);
        if (mode === 'rooms') exhibition.guideOpen = true;
      }
      await document.fonts.ready;
      await wait(2200);
      document.activeElement?.blur();
      mark('recording');
    } else if (mode === 'entrance') {
      const style=document.createElement('style');style.textContent='.exhibition-header,.exhibition-footer{visibility:hidden!important}';document.head.append(style);
      await wait(2200);
      document.activeElement?.blur();
      mark('recording');
    } else if (mode === 'audio') {
      const index=workPassage(exhibition.exhibition, 'fragments:identity-interview-reflection');
      exhibition.goStep(index, true);
      await until(()=>!exhibition.audioBusy && document.querySelector('.exhibition-story-prose')?.textContent.length>50);
      await wait(1800);
      const audio=document.querySelector('.exhibition-audio audio');
      // Warm the real player before the take, then return to its initial state.
      const startButton=document.querySelector('.exhibition-audio > button');
      startButton.click();
      await until(()=>!audio.paused && audio.currentTime>0);
      startButton.click();
      audio.currentTime=0;
      const nextAudio=new Audio();
      nextAudio.crossOrigin='anonymous';nextAudio.preload='auto';
      const nextStep=exhibitionAdjacentVisitStep(exhibition.exhibition,index);
      const nextCue=exhibitionNarrationCue(exhibition.exhibition,nextStep);
      const nextUrl=new URL(audio.currentSrc);
      nextUrl.pathname=nextUrl.pathname.replace(/\/[^/]+$/,`/${nextCue.section}`);
      nextUrl.searchParams.set('part',nextCue.part);
      nextAudio.src=nextUrl.href;nextAudio.load();
      await until(()=>nextAudio.readyState>=3);
      await wait(250);
      const audioRegion=['.exhibition-audio','.exhibition-audio-here'];
      focusElements(['.exhibition-story',audioRegion]);
      const recordingStart=await beginAudioCapture();
      const finishAudio=trackRecordedAudio(audio,recordingStart,()=>exhibition.audioText,()=>exhibition.audioWordIndex);
      const events=[];
      const note=name=>events.push({name,time:(performance.now()-recordingStart)/1000});
      const at=seconds=>wait(Math.max(0,seconds*1000-(performance.now()-recordingStart)));
      await wait(800);
      await captureClick(document.querySelector('.exhibition-audio > button'));
      await until(()=>!audio.paused && audio.currentTime>0);
      note('first-passage');
      const firstSource=audio.currentSrc;
      await at(7.8631);
      focusElements(['.exhibition-story',audioRegion,'.exhibition-navigation']);
      await wait(500);
      note('next-click');
      await captureClick(document.querySelector('.exhibition-navigation [aria-label="Next stop"]'));
      await until(()=>!exhibition.cameraTravelling && document.querySelector('.exhibition-audio-here'));
      if(audio.currentSrc!==firstSource||audio.paused)throw new Error('The first passage did not continue during the walk');
      note('listen-here-visible');
      focusElements(['.exhibition-story',audioRegion]);
      await at(13.5535);
      note('listen-here-click');
      await captureClick(document.querySelector('.exhibition-audio-here'));
      await until(()=>audio.currentSrc!==firstSource && !audio.paused && audio.currentTime>0);
      note('current-passage');
      await at(22.4);
      audio.pause();
      const segments=finishAudio();
      await wait(400);
      mark('finished',JSON.stringify({segments,events,slate:true,duration:22.8}));
    } else if (mode === 'translation') {
      // Begin with the actual original text, then use the public language menu.
      exhibition.$emit('select-translation','');
      await wait(1500);
      mark('recording');
      await wait(1100);
      focusElements(['.exhibition-tools .translation-action']);
      await wait(700);
      await captureClick(document.querySelector('.exhibition-tools .translation-action'));
      await wait(3200);
      const button=[...document.querySelectorAll('.language-options button')].find(button=>button.textContent.trim().startsWith('English'));
      if(!button)throw new Error('English option missing');
      await captureClick(button);
      await until(()=>exhibition.translationVisible && !exhibition.translationLoading);
      focusElements(['.exhibition-story','.exhibition-tools .translation-action']);
      await wait(4200);
      mark('finished');
    } else if(mode === 'lighting') {
      const finalRoom=exhibition.exhibition.rooms.at(-1);
      exhibition.goStep(finalRoom.introStep, true);
      const style=document.createElement('style');style.textContent='.exhibition-story,.exhibition-header,.exhibition-footer{visibility:hidden!important}';document.head.append(style);
      const plan=exhibition.exhibition.architecture;
      const door=plan.doors.find(door=>door.primary && door.b===plan.rooms.length-1);
      const [a,b]=door.points, dx=b[0]-a[0],dz=b[1]-a[1],length=Math.hypot(dx,dz),ux=dx/length,uz=dz/length;
      const start=[a[0]-ux*7.8,1.72,a[1]-uz*7.8];
      const end=[b[0]+ux*.8,1.72,b[1]+uz*.8];
      const pose={eye:start,yaw:Math.atan2(-ux,-uz),pitch:0,frameLift:0,entranceFrame:0};
      exhibition._scene.restoreView(pose);
      await wait(1800);
      const beginning=await beginAudioCapture(),duration=18000;
      await new Promise(resolve=>{
        function tick(now) {
          const phase=Math.min(1,(now-beginning)/duration);
          const progress=(1-Math.cos(phase*Math.PI*2))/2;
          exhibition._scene.restoreView({...pose,eye:start.map((value,index)=>value+(end[index]-value)*progress)});
          if(phase<1)requestAnimationFrame(tick);else resolve();
        }
        requestAnimationFrame(tick);
      });
      mark('finished',JSON.stringify({slate:true,duration:18}));
    }
  } catch(error) { mark('error',error.message); }
}
